all_candidates.sql:
SELECT \"nct\", \"author\", \"year\", \"pubmed_id\" FROM public.\"clinical_trials\" WHERE \"cancer_type\" ILIKE '%gastric%' OR \"cancer_type\" ILIKE '%gej%' AND \"is_any_other_biomarker_used_for_inclusion_criteria\" = true AND \"is_pd_l1_positivity_inclusion_criteria\" = false",
  "answer": "Gastric/GEJ trials requiring a biomarker other than PD-L1 for inclusion.",
  "assumptions": "Assumed that 'GEJ' refers to Gastric/GEJ cancer and that the inclusion criteria specify other biomarkers besides PD-L1."
}
